traveller_count']) ?>"></div><div class="field"><label for="budget">Budget</label><input id="budget" type="number" min="0" step="0.01" name="budget" value="<?= nh_e($enquiry['budget']) ?>"></div><div class="field"><label for="source">Source</label><input id="source" name="source" value="<?= nh_e($enquiry['source']) ?>"></div><div class="field span-2"><label for="internal_notes">Private internal notes</label><textarea id="internal_notes" name="internal_notes"><?= nh_e($enquiry['internal_notes']) ?></textarea></div></div><button class="btn" type="submit">Save enquiry updates</button></form></section><?php endif ?>
