can('followups.manage')): ?><form method="post" action="<?= nh_e(APP_BASE_PATH) ?>/admin/enquiries/followups/complete?id=<?= (int) $enquiry['id'] ?>"><input type="hidden" name="_csrf" value="<?= nh_e(Csrf::token()) ?>"><input type="hidden" name="followup_id" value="<?= (int) $f['id'] ?>"><button class="btn secondary small" type="submit">Mark done</button></form><?php endif ?></td></tr><?php endforeach ?><?php if (!$followups): ?><tr><td colspan="6" class="muted">No follow-ups recorded yet.</td></tr><?php endif ?></tbody></table></div></section>
